import{_ as t,c as a,o,aj as r}from"./chunks/framework.CDhdelVI.js";const g=JSON.parse('{"title":"Getting Started With KitchenRatio","description":"","frontmatter":{},"headers":[],"relativePath":"guides/getting-started.md","filePath":"guides/getting-started.md"}'),i={name:"guides/getting-started.md"};function n(s,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started-with-kitchenratio" tabindex="-1">Getting Started With KitchenRatio <a class="header-anchor" href="#getting-started-with-kitchenratio" aria-label="Permalink to “Getting Started With KitchenRatio”">​</a></h1><p>KitchenRatio helps you build, scale, and plan dough formulas without losing the thread between style, size, and process. If you want the shortest path: choose what you want to make, pick a preset, set your yield target, and go straight to the recipe.</p><h2 id="_1-start-with-what-you-want-to-make" tabindex="-1">1. Start With What You Want To Make <a class="header-anchor" href="#_1-start-with-what-you-want-to-make" aria-label="Permalink to “1. Start With What You Want To Make”">​</a></h2><p>The preset flow now starts by category:</p><ul><li>Pizza</li><li>Bread</li><li>Flatbread</li></ul><p>From there, choose a featured preset card with a short description and use <strong>Instructions</strong> if you want a matching recipe guide before you tweak anything.</p><p>Presets are meant to be fast starting points, not locked templates. If you change the formula or process, the preset switches to <strong>Customized</strong> and you can use <strong>Revert to preset</strong> to get back to the original baseline.</p><h2 id="_2-set-your-yield-first" tabindex="-1">2. Set Your Yield First <a class="header-anchor" href="#_2-set-your-yield-first" aria-label="Permalink to “2. Set Your Yield First”">​</a></h2><p>The <strong>Yield Planner</strong> is now a primary part of the workflow. Pick the planning mode that matches how you think:</p><ul><li><strong>Portions</strong> when you want a target number of dough balls, rolls, or tortillas</li><li><strong>Total dough</strong> when you want a specific finished dough weight</li><li><strong>Flour</strong> when you already know your flour amount</li></ul><p>Planner state persists on refresh, so you can leave and come back without rebuilding your batch.</p><p>When you switch presets, KitchenRatio keeps your active planner target instead of forcing you to start over. That means your portions or total-dough target stays intact while you compare styles.</p><h2 id="_3-use-chips-and-controls-to-dial-in-size-fast" tabindex="-1">3. Use Chips And Controls To Dial In Size Fast <a class="header-anchor" href="#_3-use-chips-and-controls-to-dial-in-size-fast" aria-label="Permalink to “3. Use Chips And Controls To Dial In Size Fast”">​</a></h2><p>Use the custom <code>+</code> and <code>-</code> controls or type directly into planner inputs. Inputs no longer clamp aggressively while you are typing, which makes it much easier to enter exact targets.</p><p>Quick chips help you land on common batch sizes faster:</p><ul><li>grams-per-portion chips that change by category</li><li>pizza style chips that pin relevant dough weights first</li><li>loaf chips including <strong>1.5 lb</strong> and <strong>2 lb</strong></li><li>tortillas adjusted to <strong>45g</strong></li></ul><p>This makes the planner useful for both rough sizing and repeatable production.</p><h2 id="_4-tune-the-formula" tabindex="-1">4. Tune The Formula <a class="header-anchor" href="#_4-tune-the-formula" aria-label="Permalink to “4. Tune The Formula”">​</a></h2><p>Once yield is set, adjust the formula in <strong>Formula</strong>:</p><ul><li>Hydration</li><li>Salt</li><li>Yeast</li><li>Water temperature</li><li>Ingredient additions and flour blends</li></ul><p>Preset values give you a strong baseline, but you can still move the dough where you want it. Recent preset updates include:</p><ul><li>New York style pizza at <strong>64% hydration</strong></li><li>Margot&#39;s Midwest Thin at <strong>48% hydration</strong></li></ul><p>If you change a preset and want to compare against the original again, use <strong>Revert to preset</strong>.</p><h2 id="_5-plan-fermentation-around-your-schedule" tabindex="-1">5. Plan Fermentation Around Your Schedule <a class="header-anchor" href="#_5-plan-fermentation-around-your-schedule" aria-label="Permalink to “5. Plan Fermentation Around Your Schedule”">​</a></h2><p>KitchenRatio now handles fermentation planning with more preset awareness and better long-fridge behavior.</p><p>You can:</p><ul><li>use preset-aware schedule profiles</li><li>lock <strong>Bulk</strong> and <strong>Proofing</strong> back to the preset schedule</li><li>set custom min/max fermentation windows</li><li>save those custom windows with the recipe</li></ul><p>This is especially useful when a dough style has a distinct process. For example, Margot&#39;s Midwest Thin now reflects:</p><ul><li><strong>24h bulk</strong></li><li><strong>48-72h proof</strong></li></ul><p>The cold-ferment estimator is more reliable for longer refrigerator timelines, so the planning output is closer to how these doughs are actually used.</p><h2 id="_6-read-the-stats-without-the-clutter" tabindex="-1">6. Read The Stats Without The Clutter <a class="header-anchor" href="#_6-read-the-stats-without-the-clutter" aria-label="Permalink to “6. Read The Stats Without The Clutter”">​</a></h2><p>The stats area is simpler and easier to scan. Use it to understand both the formula and the expected dough behavior.</p><p>You will now see clearer hydration grouping:</p><ul><li><strong>Base</strong></li><li><strong>Effective</strong></li><li><strong>Adjusted</strong></li></ul><p>You also get a texture forecast summary to help you read the formula in practical terms:</p><ul><li>dough feel</li><li>crumb</li><li>crust</li></ul><p>Proofing controls were moved into <strong>Formula</strong>, where they are easier to adjust while building the dough.</p><h2 id="_7-review-recipe-and-timing" tabindex="-1">7. Review Recipe And Timing <a class="header-anchor" href="#_7-review-recipe-and-timing" aria-label="Permalink to “7. Review Recipe And Timing”">​</a></h2><p>The <strong>Recipe</strong> view reflects your current formula, yield target, and saved planning choices. Use it to confirm ingredient weights, process timing, and fermentation windows before baking.</p><p>The <strong>Time to Bake Planner</strong> now opens and closes like the other cards, so it behaves more consistently while you move through the workflow.</p><p>Use <strong>Share Recipe</strong> to copy a URL with your current settings if you want to save or send the formula.</p><h2 id="_8-mobile-workflow-is-faster" tabindex="-1">8. Mobile Workflow Is Faster <a class="header-anchor" href="#_8-mobile-workflow-is-faster" aria-label="Permalink to “8. Mobile Workflow Is Faster”">​</a></h2><p>On mobile, KitchenRatio now keeps the active plan easier to reach with a sticky <strong>Current plan</strong> bar. It shows:</p><ul><li>current style and size summary</li><li>a <strong>Customized</strong> badge when you changed the preset</li><li>quick actions for <strong>Size</strong> and <strong>Recipe</strong></li></ul><p>Sticky actions now scroll with an offset so top content is not hidden, and tapping the style name jumps you back to presets.</p><h2 id="_9-move-between-tabs-more-smoothly" tabindex="-1">9. Move Between Tabs More Smoothly <a class="header-anchor" href="#_9-move-between-tabs-more-smoothly" aria-label="Permalink to “9. Move Between Tabs More Smoothly”">​</a></h2><p>The <strong>Formula</strong>, <strong>Recipe</strong>, and <strong>Stats</strong> views have improved mobile and desktop tab behavior. The redundant recipe preview card is gone, and layout behavior around the tablet breakpoint has been cleaned up so you do not end up with awkward empty space.</p><h2 id="_10-if-you-want-the-quick-version" tabindex="-1">10. If You Want The Quick Version <a class="header-anchor" href="#_10-if-you-want-the-quick-version" aria-label="Permalink to “10. If You Want The Quick Version”">​</a></h2><p>Here is the repeatable workflow:</p><ol><li>Choose a category and preset.</li><li>Set yield with <strong>Portions</strong>, <strong>Total dough</strong>, or <strong>Flour</strong>.</li><li>Use chips or controls to hit the batch size you want.</li><li>Adjust the formula and fermentation plan.</li><li>Check stats for hydration and texture forecast.</li><li>Review <strong>Recipe</strong> and <strong>Time to Bake Planner</strong>.</li><li>Share or bake.</li></ol><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul>',52)])])}const p=t(i,[["render",n]]);export{g as __pageData,p as default};
